"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[6152],{60926(e){e.exports=JSON.parse('{"tag":{"label":"natural-proofs","permalink":"/azeon/p-vs-np/tags/natural-proofs","allTagsPath":"/azeon/p-vs-np/tags","count":4,"items":[{"id":"failed-proofs/cryptography-vs-natural-proofs","title":"Cryptography vs. Natural Proofs","description":"Secure encryption needs functions that look random but aren\'t. If such functions exist, they hide their own simplicity so well that the natural way of proving hardness can\'t see it. The thing we want to prove protects itself.","permalink":"/azeon/p-vs-np/failed-proofs/cryptography-vs-natural-proofs"},{"id":"failed-proofs/summary-of-the-barriers","title":"Summary of the Barriers","description":"Phase 4 in one place: every barrier, what it blocks, what slips past it, and the 2011 result that showed a way around all of them for a weaker question. Why a proof may need mathematics that doesn\'t exist yet.","permalink":"/azeon/p-vs-np/failed-proofs/summary-of-the-barriers"},{"id":"failed-proofs/the-natural-proofs-barrier","title":"The Natural Proofs Barrier","description":"Razborov and Rudich noticed that every circuit lower bound proof of their time had the same simple shape. Then they proved that, if strong cryptography exists, no proof of that shape can ever separate P from NP.","permalink":"/azeon/p-vs-np/failed-proofs/the-natural-proofs-barrier"},{"id":"failed-proofs/why-havent-we-solved-it","title":"Why Haven\'t We Solved It?","description":"Over fifty years, thousands of researchers, and almost no progress on the main question. It\'s not lack of effort. It\'s that mathematicians have proved, three separate times, that whole families of proof techniques cannot work.","permalink":"/azeon/p-vs-np/failed-proofs/why-havent-we-solved-it"}],"unlisted":false}}')}}]);